CREATE SCHEMA IF NOT EXISTS app;
REVOKE ALL ON SCHEMA app FROM PUBLIC;
CREATE TABLE IF NOT EXISTS app.migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text, verified boolean NOT NULL DEFAULT false, role text NOT NULL DEFAULT 'investor' CHECK(role IN ('investor','reviewer','admin','superadmin')), adult_confirmed boolean NOT NULL DEFAULT false, terms_accepted boolean NOT NULL DEFAULT false, preferences jsonb NOT NULL DEFAULT '{"theme":"system","language":"en","motion":"system","notifications":true}', deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.mail (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, kind text NOT NULL, token_hash text NOT NULL UNIQUE, local_token text, consumed_at timestamptz, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.businesses (id text PRIMARY KEY, name text NOT NULL, tagline text NOT NULL DEFAULT '', sector text NOT NULL, location text NOT NULL, story text NOT NULL DEFAULT '', founder_name text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','needs-information','under-review','approved','rejected','published')), stage text NOT NULL DEFAULT 'Growing', illustration text NOT NULL DEFAULT 'leaf', color text NOT NULL DEFAULT '#BCE9D8', risks jsonb NOT NULL DEFAULT '[]', funding_use jsonb NOT NULL DEFAULT '[]', private_details jsonb NOT NULL DEFAULT '{}', reviewer_id uuid REFERENCES app.users, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.memberships (business_id text REFERENCES app.businesses, user_id uuid REFERENCES app.users, role text NOT NULL DEFAULT 'owner', PRIMARY KEY(business_id,user_id));
CREATE TABLE app.financials (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES app.businesses, period text NOT NULL, revenue_paisa bigint NOT NULL CHECK(revenue_paisa>=0), variable_cost_paisa bigint NOT NULL CHECK(variable_cost_paisa>=0), operating_cost_paisa bigint NOT NULL CHECK(operating_cost_paisa>=0), opening_cash_paisa bigint NOT NULL CHECK(opening_cash_paisa>=0), source text NOT NULL, confirmed boolean NOT NULL DEFAULT false, UNIQUE(business_id,period));
CREATE TABLE app.rounds (id text PRIMARY KEY, business_id text NOT NULL REFERENCES app.businesses, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','funded-awaiting-close','closed-successfully','failed','cancelled')), target_paisa bigint NOT NULL CHECK(target_paisa>0), committed_paisa bigint NOT NULL DEFAULT 0 CHECK(committed_paisa>=0 AND committed_paisa<=target_paisa), share_price_paisa bigint NOT NULL CHECK(share_price_paisa>0), existing_shares bigint NOT NULL CHECK(existing_shares>0), pre_money_paisa bigint NOT NULL, min_paisa bigint NOT NULL, increment_paisa bigint NOT NULL CHECK(increment_paisa>0), terms_version integer NOT NULL DEFAULT 1, deadline timestamptz NOT NULL, closed_at timestamptz, CHECK(pre_money_paisa=existing_shares*share_price_paisa), CHECK(target_paisa%share_price_paisa=0), CHECK(min_paisa%share_price_paisa=0), CHECK(increment_paisa%share_price_paisa=0));
CREATE TABLE app.term_versions (round_id text REFERENCES app.rounds, version integer NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(round_id,version));
CREATE TABLE app.accounts (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('issuance','available','escrow','proceeds')), user_id uuid REFERENCES app.users, round_id text REFERENCES app.rounds, normal_balance text NOT NULL CHECK(normal_balance IN ('debit','credit')));
CREATE TABLE app.journals (id uuid PRIMARY KEY, operation_key text NOT NULL UNIQUE, kind text NOT NULL, reversal_of uuid REFERENCES app.journals, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.entries (id bigserial PRIMARY KEY, journal_id uuid NOT NULL REFERENCES app.journals, account_id text NOT NULL REFERENCES app.accounts, amount_paisa bigint NOT NULL CHECK(amount_paisa<>0));
CREATE INDEX entries_account ON app.entries(account_id);
CREATE FUNCTION app.prevent_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'The virtual ledger is append only'; END $$;
CREATE TRIGGER immutable_entries BEFORE UPDATE OR DELETE ON app.entries FOR EACH ROW EXECUTE FUNCTION app.prevent_ledger_mutation();
CREATE TRIGGER immutable_journals BEFORE UPDATE OR DELETE ON app.journals FOR EACH ROW EXECUTE FUNCTION app.prevent_ledger_mutation();
CREATE FUNCTION app.check_balanced_journal() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE total bigint; BEGIN SELECT sum(amount_paisa) INTO total FROM app.entries WHERE journal_id=NEW.journal_id; IF total<>0 THEN RAISE EXCEPTION 'Unbalanced virtual journal'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT ON app.entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.check_balanced_journal();
CREATE TABLE app.quotes (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, round_id text NOT NULL REFERENCES app.rounds, amount_paisa bigint NOT NULL CHECK(amount_paisa>0), shares bigint NOT NULL, terms_version integer NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.commitments (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, round_id text NOT NULL REFERENCES app.rounds, quote_id uuid NOT NULL UNIQUE REFERENCES app.quotes, amount_paisa bigint NOT NULL CHECK(amount_paisa>0), shares bigint NOT NULL CHECK(shares>0), terms_version integer NOT NULL, report_id uuid, status text NOT NULL CHECK(status IN ('committed','cancelled','refunded','issued')), idempotency_key text NOT NULL, request_hash text NOT NULL, journal_id uuid NOT NULL REFERENCES app.journals, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE app.allocations (id uuid PRIMARY KEY, commitment_id uuid NOT NULL UNIQUE REFERENCES app.commitments, user_id uuid NOT NULL REFERENCES app.users, round_id text NOT NULL REFERENCES app.rounds, shares bigint NOT NULL, cost_paisa bigint NOT NULL, total_shares bigint NOT NULL, issued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.cap_table_events (id uuid PRIMARY KEY, round_id text NOT NULL UNIQUE REFERENCES app.rounds, new_shares bigint NOT NULL, founder_shares bigint NOT NULL, total_shares bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.saved (user_id uuid REFERENCES app.users, business_id text REFERENCES app.businesses, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,business_id));
CREATE TABLE app.documents (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES app.businesses, uploader_id uuid NOT NULL REFERENCES app.users, name text NOT NULL, mime_type text NOT NULL, size_bytes integer NOT NULL CHECK(size_bytes<=5242880), version integer NOT NULL, storage_path text UNIQUE NOT NULL, status text NOT NULL CHECK(status IN ('quarantined','clean','rejected','scanner-unavailable','controlled-sample')), scan_engine text, sha256 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,name,version));
CREATE TABLE app.document_links (token_hash text PRIMARY KEY, document_id uuid NOT NULL REFERENCES app.documents, user_id uuid NOT NULL REFERENCES app.users, expires_at timestamptz NOT NULL);
CREATE TABLE app.review_events (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES app.businesses, actor_id uuid NOT NULL REFERENCES app.users, decision text NOT NULL, notes text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.verification_checks (business_id text REFERENCES app.businesses, kind text NOT NULL, outcome text NOT NULL, reviewer_id uuid NOT NULL REFERENCES app.users, notes text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,kind));
CREATE TABLE app.reports (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES app.businesses, version integer NOT NULL, status text NOT NULL CHECK(status IN ('draft','published','rejected')), prepared_by uuid NOT NULL REFERENCES app.users, approved_by uuid REFERENCES app.users, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, UNIQUE(business_id,version), CHECK(approved_by IS NULL OR approved_by<>prepared_by));
ALTER TABLE app.commitments ADD CONSTRAINT commitments_report_fk FOREIGN KEY(report_id) REFERENCES app.reports(id);
CREATE TABLE app.updates (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES app.businesses, author_id uuid NOT NULL REFERENCES app.users, title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','removed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.notifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, event_key text NOT NULL UNIQUE, title text NOT NULL, body text NOT NULL, link text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.jobs (id uuid PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, event_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','complete','failed')), attempts integer NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), leased_until timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_pending ON app.jobs(status,run_at);
CREATE TABLE app.support_requests (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.deletion_requests (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app.users, status text NOT NULL, details text NOT NULL, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.moderation (id uuid PRIMARY KEY, reporter_id uuid NOT NULL REFERENCES app.users, business_id text NOT NULL REFERENCES app.businesses, reason text NOT NULL, status text NOT NULL DEFAULT 'pending', decision_by uuid REFERENCES app.users, decision_notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.audit (id bigserial PRIMARY KEY, actor_id uuid REFERENCES app.users, action text NOT NULL, target text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON ALL TABLES IN SCHEMA app FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app FROM PUBLIC;
